<script>
(function () {
  "use strict";

  var PASSWORD_MIN_LENGTH = 8;

  var form = document.getElementById("signup-form");
  var status = document.getElementById("form-status");
  var emailAscii = document.getElementById("email-ascii");
  var websiteAscii = document.getElementById("website-ascii");

  /* ---------- Noms de domaine ---------- */

  // Vérifie un nom d'hôte déjà converti en A-labels (ASCII, minuscules).
  // Aucune liste de TLD ni longueur maximale de TLD autre que celle d'un label :
  // un TLD est soit composé d'au moins deux lettres, soit un A-label « xn-- ».
  function isValidAsciiHostname(host) {
    if (host === "" || host.length > 253) { return false; }
    var labels = host.split(".");
    if (labels.length < 2) { return false; }
    for (var i = 0; i < labels.length; i++) {
      // 1 à 63 octets, lettres, chiffres et tirets, sans tiret aux extrémités.
      if (!/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(labels[i])) {
        return false;
      }
    }
    var tld = labels[labels.length - 1];
    return /^[a-z]{2,}$/.test(tld) || /^xn--/.test(tld);
  }

  // Convertit un domaine saisi (U-labels ou A-labels, casse quelconque) en
  // A-labels grâce à l'analyseur d'URL du navigateur (UTS #46), puis le vérifie.
  // Renvoie la forme ASCII, ou null si le domaine n'est pas valide.
  function domainToAscii(domain) {
    // Caractères que l'analyseur d'URL interpréterait autrement que comme
    // une partie du nom d'hôte (chemin, port, identifiants, IPv6, etc.).
    if (domain === "" || /[\s\/\\?#@:\[\]%]/.test(domain)) { return null; }
    var host;
    try {
      host = new URL("http://" + domain).hostname;
    } catch (e) {
      return null;
    }
    return isValidAsciiHostname(host) ? host : null;
  }

  function utf8Length(text) {
    return new TextEncoder().encode(text).length;
  }

  /* ---------- Validation de chaque champ ---------- */
  // Chaque fonction renvoie { error: "message ou chaîne vide", ascii: "..." }.

  function validateFullname(raw) {
    if (raw.trim() === "") {
      return { error: "Indiquez votre nom complet." };
    }
    return { error: "" };
  }

  function validateEmail(raw) {
    var value = raw.trim();
    if (value === "") {
      return { error: "Indiquez votre adresse e-mail." };
    }
    if (/\s/.test(value)) {
      return { error: "L'adresse e-mail ne doit pas contenir d'espace." };
    }
    var parts = value.split("@");
    if (parts.length < 2) {
      return { error: "L'adresse e-mail doit contenir un « @ »." };
    }
    if (parts.length > 2) {
      return { error: "L'adresse e-mail ne doit contenir qu'un seul « @ »." };
    }
    var local = parts[0];
    var domain = parts[1];
    if (local === "") {
      return { error: "Il manque la partie située avant le « @ »." };
    }
    if (utf8Length(local) > 64) {
      return { error: "La partie située avant le « @ » est trop longue." };
    }
    if (domain === "") {
      return { error: "Il manque le domaine après le « @ »." };
    }
    var asciiDomain = domainToAscii(domain);
    if (asciiDomain === null) {
      return {
        error: "Le domaine après le « @ » n'est pas valide " +
               "(exemple attendu : nom@exemple.fr)."
      };
    }
    // La partie locale est conservée telle quelle (Unicode autorisé, RFC 6531).
    return { error: "", ascii: local + "@" + asciiDomain };
  }

  function validateWebsite(raw) {
    var value = raw.trim();
    if (value === "") {
      return { error: "", ascii: "" }; // champ facultatif
    }
    var candidate = value;
    if (!/^https?:\/\//i.test(value)) {
      if (/^[a-z][a-z0-9+.-]*:\/\//i.test(value)) {
        return { error: "L'adresse du site doit commencer par http:// ou https://." };
      }
      candidate = "https://" + value; // « exemple.fr » est accepté tel quel
    }
    var url;
    try {
      url = new URL(candidate);
    } catch (e) {
      return {
        error: "Cette adresse de site n'est pas valide " +
               "(exemple attendu : https://exemple.fr)."
      };
    }
    // url.hostname est déjà converti en A-labels par le navigateur.
    if (!isValidAsciiHostname(url.hostname)) {
      return {
        error: "Le nom de domaine du site n'est pas valide " +
               "(exemple attendu : https://exemple.fr)."
      };
    }
    return { error: "", ascii: url.href };
  }

  function validatePassword(raw) {
    if (raw === "") {
      return { error: "Choisissez un mot de passe." };
    }
    if (Array.from(raw).length < PASSWORD_MIN_LENGTH) {
      return {
        error: "Le mot de passe doit contenir au moins " +
               PASSWORD_MIN_LENGTH + " caractères."
      };
    }
    return { error: "" };
  }

  var fields = [
    { id: "fullname", validate: validateFullname },
    { id: "email",    validate: validateEmail,   asciiTarget: emailAscii },
    { id: "website",  validate: validateWebsite, asciiTarget: websiteAscii },
    { id: "password", validate: validatePassword }
  ];

  /* ---------- Affichage des erreurs ---------- */

  function checkField(field) {
    var input = document.getElementById(field.id);
    var errorBox = document.getElementById(field.id + "-error");
    var result = field.validate(input.value);

    errorBox.textContent = result.error;
    if (result.error) {
      input.setAttribute("aria-invalid", "true");
    } else {
      input.removeAttribute("aria-invalid");
    }
    if (field.asciiTarget) {
      field.asciiTarget.value = result.error ? "" : (result.ascii || "");
    }
    return result.error === "";
  }

  fields.forEach(function (field) {
    var input = document.getElementById(field.id);

    // Vérification en quittant le champ…
    input.addEventListener("blur", function () {
      if (input.value !== "" || input.hasAttribute("aria-invalid")) {
        checkField(field);
      }
    });
    // …puis correction en direct dès qu'une erreur est affichée.
    input.addEventListener("input", function () {
      status.textContent = "";
      if (input.hasAttribute("aria-invalid")) {
        checkField(field);
      }
    });
  });

  document.getElementById("toggle-password").addEventListener("change", function (event) {
    document.getElementById("password").type = event.target.checked ? "text" : "password";
  });

  /* ---------- Envoi ---------- */

  form.addEventListener("submit", function (event) {
    var firstInvalid = null;

    fields.forEach(function (field) {
      if (!checkField(field) && firstInvalid === null) {
        firstInvalid = document.getElementById(field.id);
      }
    });

    if (firstInvalid !== null) {
      event.preventDefault();
      status.className = "failure";
      status.textContent = "Le formulaire contient des erreurs : corrigez les champs signalés.";
      firstInvalid.focus();
      return;
    }

    // Espaces superflus retirés en début et fin (jamais dans le mot de passe).
    ["fullname", "email", "website"].forEach(function (id) {
      var input = document.getElementById(id);
      input.value = input.value.trim();
    });

    if (!form.hasAttribute("action")) {
      // Page autonome : pas de serveur, on confirme simplement la validation.
      event.preventDefault();
      status.className = "success";
      status.textContent = "Tous les champs sont valides : inscription prête à être envoyée.";
    }
    // Avec un attribut « action », l'envoi natif du formulaire se poursuit.
  });
})();
</script>
</body>
